static parseKeybinding(input) {
        if (!input) {
            return null;
        }
        const chords = [];
        let chord;
        while (input.length > 0) {
            [chord, input] = this.b(input);
            chords.push(chord);
        }
        return (chords.length > 0 ? new $cf(chords) : null);
